interface.signature:
@ControllerAdvice
@ResponseBody
public class GlobalExceptionHandler {

  @ExceptionHandler(MethodArgumentNotValidException.class)
  public ResponseEntity<StandardErrorResponse> handleValidationException(MethodArgumentNotValidException ex) {
    List<FieldError> fieldErrors = extractFieldErrors(ex.getBindingResult());
    ErrorDetails errorDetails = new ErrorDetails("VALIDATION_ERROR", "Validation failed", fieldErrors);
    return ResponseEntity.badRequest().body(new StandardErrorResponse(errorDetails, getMetadata()));
  }

  @ExceptionHandler(CustomerNotFoundException.class)
  public ResponseEntity<StandardErrorResponse> handleNotFound(CustomerNotFoundException ex) {
    ErrorDetails errorDetails = new ErrorDetails("NOT_FOUND", ex.getMessage(), null);
    return ResponseEntity.status(HttpStatus.NOT_FOUND).body(new StandardErrorResponse(errorDetails, getMetadata()));
  }

  @ExceptionHandler(CustomerAlreadyExistsException.class)
  public ResponseEntity<StandardErrorResponse> handleConflict(CustomerAlreadyExistsException ex) {
    ErrorDetails errorDetails = new ErrorDetails("CONFLICT", ex.getMessage(), null);
    return ResponseEntity.status(HttpStatus.CONFLICT).body(new StandardErrorResponse(errorDetails, getMetadata()));
  }

  @ExceptionHandler(Exception.class)
  public ResponseEntity<StandardErrorResponse> handleGenericException(Exception ex) {
    ErrorDetails errorDetails = new ErrorDetails("INTERNAL_ERROR", "An unexpected error occurred", null);
    return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(new StandardErrorResponse(errorDetails, getMetadata()));
  }
}

public class StandardErrorResponse {
  private ErrorDetails error;
  private Map<String, Object> metadata; // timestamp, traceId

  public static class ErrorDetails {
    private String code;
    private String message;
    private List<FieldError> details;
  }

  public static class FieldError {
    private String field;
    private String message;
    private Object value;
    private String code;
  }
}
